package com.videoshare.feed;

import com.videoshare.auth.CurrentUser;import com.videoshare.common.*;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1")
public class SocialController {
    private final SocialService service;private final IdempotencyService idempotency;public SocialController(SocialService service,IdempotencyService idempotency){this.service=service;this.idempotency=idempotency;}
    @GetMapping("/feeds")public ApiResponse<Map<String,Object>>feeds(@RequestParam(defaultValue="recommend")String type,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="10")int pageSize,@AuthenticationPrincipal CurrentUser c){return ApiResponse.ok(service.feeds(type,cursor,pageSize,c==null?null:c.id(),null));}
    @GetMapping("/feeds/{id}")public ApiResponse<Map<String,Object>>feed(@PathVariable long id,@AuthenticationPrincipal CurrentUser c){return ApiResponse.ok(service.feed(id,c==null?null:c.id()));}
    @PostMapping("/feeds")public ApiResponse<Map<String,Object>>publish(@AuthenticationPrincipal CurrentUser c,@RequestHeader(name="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object>b){long user=require(c);return ApiResponse.ok(idempotency.execute(user,"feed:publish",key,()->service.publish(user,b)));}
    @DeleteMapping("/feeds/{id}")public ApiResponse<Map<String,Boolean>>remove(@PathVariable long id,@AuthenticationPrincipal CurrentUser c){service.remove(require(c),id,c.role()==com.videoshare.user.Role.ADMIN);return ApiResponse.ok(Map.of("success",true));}
    @PostMapping("/feeds/{id}/like")public ApiResponse<Map<String,Object>>like(@PathVariable long id,@AuthenticationPrincipal CurrentUser c,@RequestBody Map<String,String>b){return ApiResponse.ok(service.like(require(c),id,"LIKE".equals(b.get("action"))));}
    @PostMapping("/feeds/{id}/repost")public ApiResponse<Map<String,Object>>repost(@PathVariable long id,@AuthenticationPrincipal CurrentUser c,@RequestHeader(name="Idempotency-Key",required=false)String key){long user=require(c);return ApiResponse.ok(idempotency.execute(user,"feed:repost:"+id,key,()->Map.of("count",service.repost(user,id))));}
    @GetMapping("/feeds/{id}/comments")public ApiResponse<Map<String,Object>>comments(@PathVariable long id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@AuthenticationPrincipal CurrentUser c){return ApiResponse.ok(service.comments(id,page,pageSize,c==null?null:c.id()));}
    @PostMapping("/feeds/{id}/comments")public ApiResponse<Map<String,Object>>comment(@PathVariable long id,@AuthenticationPrincipal CurrentUser c,@RequestHeader(name="Idempotency-Key",required=false)String key,@RequestBody Map<String,String>b){long user=require(c);return ApiResponse.ok(idempotency.execute(user,"feed:comment:"+id,key,()->service.comment(user,id,b.get("content"))));}
    @GetMapping("/users/{id}/feeds")public ApiResponse<Map<String,Object>>userFeeds(@PathVariable long id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int pageSize,@AuthenticationPrincipal CurrentUser c){Map<String,Object> cursor=service.feeds("recommend",String.valueOf((page-1)*pageSize),pageSize,c==null?null:c.id(),id);Map<String,Object> result=new LinkedHashMap<>(cursor);result.put("total",cursor.get("total"));result.put("page",page);result.put("pageSize",pageSize);return ApiResponse.ok(result);}
    @PostMapping("/reports")public ApiResponse<Map<String,Object>>report(@AuthenticationPrincipal CurrentUser c,@RequestHeader(name="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object>b){long user=require(c);return ApiResponse.ok(idempotency.execute(user,"report:create",key,()->service.report(user,b)));}
    @GetMapping("/notifications")public ApiResponse<Map<String,Object>>notifications(@AuthenticationPrincipal CurrentUser c,@RequestParam(required=false)String type,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.ok(service.notifications(require(c),type,page,pageSize));}
    @GetMapping("/notifications/unread-count")public ApiResponse<Map<String,Long>>unread(@AuthenticationPrincipal CurrentUser c){return ApiResponse.ok(Map.of("count",c==null?0L:service.notifications(c.id(),null,1,1).get("unreadCount")instanceof Number n?n.longValue():0L));}
    @PostMapping("/notifications/read")public ApiResponse<Map<String,Boolean>>read(@AuthenticationPrincipal CurrentUser c,@RequestBody Map<String,Object>b){service.readNotifications(require(c),b.get("ids")instanceof List<?> ids?ids:List.of());return ApiResponse.ok(Map.of("success",true));}
    @GetMapping("/messages/conversations")public ApiResponse<List<Map<String,Object>>>conversations(@AuthenticationPrincipal CurrentUser c){return ApiResponse.ok(service.conversations(require(c)));}
    @GetMapping("/messages/conversations/{id}/messages")public ApiResponse<List<Map<String,Object>>>messages(@PathVariable long id,@AuthenticationPrincipal CurrentUser c){return ApiResponse.ok(service.messages(require(c),id));}
    @PostMapping("/messages/conversations/{id}/messages")public ApiResponse<Map<String,Object>>send(@PathVariable long id,@AuthenticationPrincipal CurrentUser c,@RequestHeader(name="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object>b){long user=require(c);return ApiResponse.ok(idempotency.execute(user,"message:send:"+id,key,()->service.sendMessage(user,id,b)));}
    private long require(CurrentUser c){if(c==null)throw new ApiException(ErrorCode.UNAUTHORIZED,"请先登录");return c.id();}
}
